package app.deckly.domain.editor

/*
 * Контрольные значения движений фигуры. Сняты вызовом функций `design/editor-shapes.js` как есть (снимок макета
 * 59c9690) в headless Chrome на временной странице вне дерева: `node` на машине нет. Лист макета 928 × 963, все числа
 * в единицах макета. Не править руками: при смене макета значения снимаются заново.
 */

/** Рамка в единицах макета: `x`, `y` — левый верхний угол до поворота, `angle` в градусах вокруг центра. */
data class DemoBox(val x: Double, val y: Double, val w: Double, val h: Double, val angle: Double)

/** Вызов `op` демо с аргументами [args] на рамке [box] вида [kind] дал [result]. */
data class DemoCase(val name: String, val kind: String, val box: DemoBox, val op: String, val args: List<Any>, val result: DemoBox)

/** Помещается ли рамка вида [kind] на лист по `canFitShape` демо. */
data class DemoFit(val kind: String, val box: DemoBox, val fits: Boolean)

